schemas:
DEFINE TABLE accounts TYPE NORMAL SCHEMAFULL;

DEFINE FIELD email ON accounts TYPE string ASSERT string::is::email($value);
DEFINE FIELD password ON accounts TYPE string;
DEFINE FIELD terms_agree ON accounts TYPE bool DEFAULT false;
DEFINE FIELD email_confirmed ON accounts TYPE bool DEFAULT false;
DEFINE FIELD created_at ON accounts TYPE datetime DEFAULT time::now() READONLY;
DEFINE FIELD updated_at ON accounts TYPE datetime DEFAULT time::now() READONLY;

DEFINE INDEX account_email_idx ON TABLE accounts COLUMNS email UNIQUE;
DEFINE TABLE script_migration SCHEMAFULL
    PERMISSIONS
        FOR select FULL
        FOR create, update, delete NONE;

DEFINE FIELD script_name ON script_migration TYPE string;
DEFINE FIELD executed_at ON script_migration TYPE datetime VALUE time::now() READONLY;
DEFINE TABLE sessions TYPE NORMAL SCHEMAFULL;

DEFINE FIELD account ON sessions TYPE record<account>;
DEFINE FIELD ip_addr ON sessions TYPE option<string> DEFAULT NONE;
DEFINE FIELD browser ON sessions TYPE option<string> DEFAULT NONE;
DEFINE FIELD device ON sessions TYPE option<string> DEFAULT NONE;
DEFINE FIELD os ON sessions TYPE option<string> DEFAULT NONE;
DEFINE FIELD created_at ON sessions TYPE datetime DEFAULT time::now() READONLY;
DEFINE FIELD expires_on ON sessions TYPE datetime DEFAULT time::now() + 4w2d READONLY;

events:
DEFINE EVENT set_account_updated_at ON TABLE accounts WHEN $event == "UPDATE" THEN (
    UPDATE accounts SET updated_at = time::now() WHERE id = $after.id
);
